<?php
function password_reset_request_key($id){return 'password_reset_request_'.(int)$id;}
function password_reset_requests($pendingOnly=true){
 if(current_user()['role']!=='Admin')return [];$q=db()->query("SELECT value_text FROM settings WHERE key_name LIKE 'password_reset_request_%'");$rows=[];foreach($q as $v){$r=json_decode($v['value_text'],true);if(is_array($r)&&isset($r['reference'],$r['user_id'])&&(!$pendingOnly||$r['status']==='Pending'))$rows[]=$r;}usort($rows,fn($a,$b)=>strcmp($b['requested_at'],$a['requested_at']));return $rows;
}
function request_password_reset($username){
 if(!is_string($username))throw new Exception('Enter a valid username.');$username=trim($username);if($username===''||strlen($username)>80)throw new Exception('Enter a username with up to 80 characters.');
 foreach(['password-reset:'.$username,'password-reset-ip'] as $key){login_rate_update($key,'check');login_rate_update($key,'failure');}
 $pdo=db();$pdo->beginTransaction();try{
  $q=$pdo->prepare('SELECT id,name,username,active,approval_status FROM users WHERE username=? FOR UPDATE');$q->execute([$username]);$u=$q->fetch();
  if(!$u||!(int)$u['active']||($u['approval_status']??'Approved')!=='Approved'){$pdo->commit();return;}
  $key=password_reset_request_key($u['id']);$pdo->prepare("INSERT IGNORE INTO settings(key_name,value_text) VALUES(?,'{}')")->execute([$key]);$q=$pdo->prepare('SELECT value_text FROM settings WHERE key_name=? FOR UPDATE');$q->execute([$key]);$old=json_decode($q->fetchColumn(),true)?:[];
  if(($old['status']??'')==='Pending'){$pdo->commit();return;}
  $history=$old['history']??[];if(isset($old['reference'])){unset($old['history']);$history[]=$old;}
  $r=['reference'=>'PWR-'.date('YmdHis').'-'.bin2hex(random_bytes(4)),'user_id'=>(int)$u['id'],'name'=>$u['name'],'username'=>$u['username'],'status'=>'Pending','requested_at'=>date('Y-m-d H:i:s'),'history'=>$history];set_setting($key,json_encode($r));audit('Password reset requested','User',(string)$u['id'],$r['reference'].'; public request; identity must be verified by an Admin.');$pdo->commit();
 }catch(Throwable $e){if($pdo->inTransaction())$pdo->rollBack();throw $e;}
}
function process_password_reset_request($input,$dismiss=false){
 if(current_user()['role']!=='Admin')throw new Exception('Administrator access required.');$id=whole_number($input['user_id']??'','User',1);$pdo=db();$pdo->beginTransaction();try{
  $q=$pdo->prepare('SELECT * FROM users WHERE id=? FOR UPDATE');$q->execute([$id]);$u=$q->fetch();if(!$u)throw new Exception('Account not found.');$key=password_reset_request_key($id);$q=$pdo->prepare('SELECT value_text FROM settings WHERE key_name=? FOR UPDATE');$q->execute([$key]);$r=json_decode($q->fetchColumn()?:'{}',true);
  if(($r['status']??'')!=='Pending'||!is_string($input['request_ref']??null)||!hash_equals((string)($r['reference']??''),$input['request_ref']))throw new Exception('This reset request has changed or was already processed. Refresh Settings.');
  if($dismiss){$reason=process_reason($input['reason']??'');$r['status']='Dismissed';$r['reason']=$reason;}
  else{if(empty($input['identity_verified']))throw new Exception('Verify the requester identity before resetting this password.');if(!(int)$u['active']||($u['approval_status']??'Approved')!=='Approved')throw new Exception('The account must be active and approved.');$pw=$input['password']??'';$confirm=$input['confirm_password']??'';if(!is_string($pw)||strlen($pw)<8||strlen($pw)>72)throw new Exception('Use a temporary password with 8–72 characters.');if($pw!==$confirm)throw new Exception('Passwords do not match.');$pdo->prepare('UPDATE users SET password_hash=?,must_change_password=1 WHERE id=?')->execute([password_hash($pw,PASSWORD_DEFAULT),$id]);$r['status']='Completed';$r['identity_verified_by']=current_user()['id'];}
  $r['processed_by']=current_user()['id'];$r['processed_name']=current_user()['name'];$r['processed_at']=date('Y-m-d H:i:s');set_setting($key,json_encode($r));audit($dismiss?'Dismiss password reset request':'Complete password reset request','User',(string)$id,$r['reference'].'; '.$r['status'].'; no password recorded in history.');$pdo->commit();
 }catch(Throwable $e){if($pdo->inTransaction())$pdo->rollBack();throw $e;}
}
function password_reset_requests_panel($userId=0,$reference='',$return='settings'){
 if(current_user()['role']!=='Admin')return;$return=$return==='admin_requests'?'admin_requests':'settings';$rows=array_values(array_filter(password_reset_requests(false),fn($r)=>(!$userId||(int)$r['user_id']===(int)$userId)&&($reference===''||$r['reference']===$reference)));echo '<div class="card table-wrap" id="password-reset-requests"><div class="card-head"><div><h3>Password Reset Requests</h3><p class="muted small">Public requests do not prove account ownership. Verify identity directly before issuing a temporary password.</p></div></div><table class="table"><tr><th>User</th><th>Requested</th><th>Status</th><th>Action</th></tr>';if(!$rows)echo '<tr><td colspan="4">No password reset requests.</td></tr>';
 foreach($rows as $r){echo '<tr><td><b>'.e($r['name']).'</b><br>'.e($r['username']).'<br><small>'.e($r['reference']).'</small></td><td>'.e($r['requested_at']).'</td><td>'.e($r['status']).'</td><td>';if($r['status']==='Pending'){$hidden='<input type="hidden" name="csrf" value="'.e(csrf_token()).'"><input type="hidden" name="return" value="'.e($return).'"><input type="hidden" name="user_id" value="'.(int)$r['user_id'].'"><input type="hidden" name="request_ref" value="'.e($r['reference']).'">';echo '<details><summary class="btn secondary sm">Verify &amp; Reset</summary><form method="post" action="actions.php" class="stack" data-confirm="Reset this verified account? Share the temporary password privately; the user must change it after signing in.">'.$hidden.'<input type="hidden" name="action" value="complete_password_reset_request"><label class="ack"><input type="checkbox" name="identity_verified" value="1" required> I verified this requester identity directly.</label><label>Temporary Password<input type="password" name="password" minlength="8" maxlength="72" autocomplete="new-password" required></label><label>Confirm Temporary Password<input type="password" name="confirm_password" minlength="8" maxlength="72" autocomplete="new-password" required></label><button class="btn danger">Reset Password</button></form><form method="post" action="actions.php" class="stack" data-confirm="Dismiss this reset request without changing the password?">'.$hidden.'<input type="hidden" name="action" value="dismiss_password_reset_request"><label>Reason to Dismiss<input name="reason" minlength="3" maxlength="1000" required></label><button class="btn ghost">Dismiss Request</button></form></details>';}else echo '<span class="muted small">'.e($r['processed_name']??'').' · '.e($r['processed_at']??'').'</span>';echo '</td></tr>';}
 echo '</table></div>';
}
